import {matchGates} from '../vendor/ato-core/src/shell-bridge.mjs';
import {BrowserTaskPlanner} from './legacy/BrowserTaskPlanner.js';import {BrowserPerceptionNavigator} from './legacy/BrowserPerceptionNavigator.js';import {BrowserOutcomeVerifier} from './legacy/BrowserOutcomeVerifier.js';import {ContactActionRouter} from './legacy/ContactActionRouter.js';
export class BrowserPlanningOrgan{constructor(){this.id='browser-planner';this.capabilities=['browser','form','research','navigation'];this.planner=new BrowserTaskPlanner();this.navigator=new BrowserPerceptionNavigator();this.verifier=new BrowserOutcomeVerifier();this.router=new ContactActionRouter();}accepts(i){return /\b(open|browse|website|site|form|apply|book|buy|research|search web)\b/i.test(i)}execute({intent,page=null}){const route=this.router.route(intent);const plan=this.planner.plan(intent,route);const next=page?this.navigator.next(page,intent,route):null;const verify=page?this.verifier.verify({route,page}):null;const grounding=matchGates(intent,{limit:3});return {ok:true,route,plan,next,verify,grounding,requiresActionSurface:true,actionSurface:'synthia-browser'};}}
export default BrowserPlanningOrgan;
